import {fiveMemberStore} from '../infrastructure/stores/sessionStoreTestSupport.js';
import {captureErrors} from '../shared/logCaptureTestSupport.js';
import {connectClient, startEngineWith, stopEngines} from './wsTestSupport.js';
import type {ChatSession} from '../types/session.js';
import type {SessionCursor, SessionListOptions, SessionStore, SessionSummary} from '../types/sessionStore.js';
import type {ErrorMessage, OutgoingMessage, SessionListMessage} from '../types/messages.js';

const sendOnConnect = (url: string, frame: unknown, token = 'u1'): Promise<OutgoingMessage> => {
  const client = connectClient(url, token);
  return new Promise(resolve => {
    client.on('message', raw => {
      const parsed = JSON.parse(String(raw)) as OutgoingMessage;
      if (parsed.type === 'connected') {
        client.send(JSON.stringify(frame));
        return;
      }
      resolve(parsed);
    });
  });
};

const listOnConnect = async (url: string, frame: Record<string, unknown>, token = 'u1'): Promise<SessionListMessage> =>
  (await sendOnConnect(url, {type: 'list_sessions', ...frame}, token)) as SessionListMessage;

const recordingListStore = (rows: SessionSummary[]) => {
  const calls: Array<{userId: string | number; options?: SessionListOptions}> = [];
  const store: SessionStore = {
    ...fiveMemberStore,
    listFor: async (userId, options) => {
      calls.push({userId, options});
      return rows;
    },
  };
  return {store, calls};
};

describe('delivering a user conversation list over WebSocket', () => {
  const errors = captureErrors();
  afterEach(stopEngines);

  it('answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId', async () => {
    const createdAt = new Date('2026-10-01T10:00:00.000Z');
    const updatedAt = new Date('2026-10-01T10:05:00.000Z');
    const {store, calls} = recordingListStore([{sessionId: 's-1', createdAt, updatedAt, entryCount: 4}]);
    const {url} = await startEngineWith({
      sessionStore: store,
      wsAuth: async req => ({id: req.headers['sec-websocket-protocol']?.includes('u2') ? 'u2' : 'u1'}),
    });
    const before: SessionCursor = {sessionId: 's-9', updatedAt: '2026-10-01T11:00:00.000Z'};

    const reply = await listOnConnect(url, {limit: 10, before, userId: 'attacker'}, 'u1');

    expect({reply, calls}).toEqual({
      reply: {
        type: 'session_list',
        sessions: [
          {
            sessionId: 's-1',
            createdAt: '2026-10-01T10:00:00.000Z',
            updatedAt: '2026-10-01T10:05:00.000Z',
            entryCount: 4,
          },
        ],
      },
      calls: [{userId: 'u1', options: {limit: 10, before}}],
    });
  });

  it('answers an empty session_list when the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws', async () => {
    const withoutListFor: SessionStore = {
      create: (sessionId, userId): ChatSession => ({sessionId, userId, entries: []}),
      get: () => undefined,
      delete: () => false,
      count: () => 0,
      clear: () => undefined,
    };
    const throwingStore: SessionStore = {
      ...withoutListFor,
      listFor: async () => {
        throw new Error('database unreachable');
      },
    };
    const {url: bareUrl} = await startEngineWith({sessionStore: withoutListFor});
    const {url: throwingUrl} = await startEngineWith({sessionStore: throwingStore});

    const bareReply = await listOnConnect(bareUrl, {});
    const failedReply = (await sendOnConnect(throwingUrl, {type: 'list_sessions'})) as ErrorMessage;

    expect({bareReply, code: failedReply.code, errors}).toEqual({
      bareReply: {type: 'session_list', sessions: []},
      code: 'SERVER_ERROR',
      errors: [{category: 'ws', message: 'session list failed', userId: 'u1', error: 'database unreachable'}],
    });
  });

  it('accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor', async () => {
    const {store, calls} = recordingListStore([]);
    const {url} = await startEngineWith({sessionStore: store});

    const badFrames = [
      {type: 'list_sessions', limit: -1},
      {type: 'list_sessions', limit: 1.5},
      {type: 'list_sessions', limit: '10'},
      {type: 'list_sessions', before: 'not-an-object'},
      {type: 'list_sessions', before: {sessionId: '', updatedAt: '2026-10-01T00:00:00.000Z'}},
      {type: 'list_sessions', before: {sessionId: 'x'.repeat(129), updatedAt: '2026-10-01T00:00:00.000Z'}},
      {type: 'list_sessions', before: {sessionId: 's-1', updatedAt: 'not-a-date'}},
      {type: 'list_sessions', before: {sessionId: 's-1'}},
    ];
    const codes: string[] = [];
    for (const frame of badFrames) {
      const reply = (await sendOnConnect(url, frame)) as ErrorMessage;
      codes.push(reply.code);
    }
    const accepted = await sendOnConnect(url, {type: 'list_sessions'});

    expect({codes, accepted, calls: calls.length}).toEqual({
      codes: Array(badFrames.length).fill('INVALID_MESSAGE'),
      accepted: {type: 'session_list', sessions: []},
      calls: 1,
    });
  });
});

