const sendOnConnect = (url: string, frame: unknown, token = 'u1'): Promise<OutgoingMessage> => {
  const client = connectClient(url, token);
  return new Promise(resolve => {
    client.on('message', raw => {
      const parsed = JSON.parse(String(raw)) as OutgoingMessage;
      if (parsed.type === 'connected') {
        client.send(JSON.stringify(frame));
        return;
      }
      resolve(parsed);
    });
  });
};

